derivation_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Treatment regimen" AS source_value FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Type of combination" = 'ICI+MEKi'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_meki_agents(source_value) AS "meki_agents"
FROM base;
